def get_builtin_skill(identifier: str) -> dict[str, Any] | None:
    """Look up a builtin skill by identifier or display name."""
    normalized = identifier.lower()
    for skill in BUILTIN_SKILLS:
        if skill["identifier"] == identifier or str(skill["name"]).lower() == normalized:
            return skill
    return None


def list_builtin_skill_identifiers() -> list[str]:
    return [skill["identifier"] for skill in BUILTIN_SKILLS]
